pub fn config(&self, inputs: &[Input]) -> Result<Config> {
    let style_components = self.style_components()?;

    let paging_mode = match self.matches.get_one::<String>("paging").map(|s| s.as_str()) {
        Some("always") => PagingMode::Always,
        Some("never") => PagingMode::Never,
        Some("auto") | None => {
            // If we have -pp as an option when in auto mode, the pager should be disabled.
            let extra_plain = self.matches.get_count("plain") > 1;
            if extra_plain || self.matches.get_flag("no-paging") {
                PagingMode::Never
            } else if inputs.iter().any(Input::is_stdin) {
                // If we are reading from stdin, only enable paging if we write to an
                // interactive terminal and if we do not *read* from an interactive
                // terminal.
                if self.interactive_output && !std::io::stdin().is_terminal() {
                    PagingMode::QuitIfOneScreen
                } else {
                    PagingMode::Never
                }
            } else if self.interactive_output {
                PagingMode::QuitIfOneScreen
            } else {
                PagingMode::Never
            }
        }
        _ => unreachable!("other values for --paging are not allowed"),
    };

    let syntax_mapping = self.syntax_mapping_from_matches()?;
    let maybe_term_width = self.terminal_width_from_matches();

    Ok(Config {
        true_color: Self::is_truecolor_terminal(),
        language: self.language_from_matches(),
        show_nonprintable: self.matches.get_flag("show-all"),
        nonprintable_notation: self.nonprintable_notation_from_matches(),
        binary: self.binary_behavior_from_matches(),
        wrapping_mode: self.wrapping_mode_from_matches(&style_components, maybe_term_width),
        colored_output: self.colored_output_from_matches(),
        paging_mode,
        term_width: maybe_term_width.unwrap_or(Term::stdout().size().1 as usize),
        loop_through: self.loop_through_from_matches(),
        tab_width: self.tab_width_from_matches(&style_components, paging_mode),
        strip_ansi: self.strip_ansi_from_matches(),
        theme: self.theme_from_matches(),
        visible_lines: self.visible_lines_from_matches()?,
        style_components,
        syntax_mapping,
        pager: self.pager_from_matches(),
        use_italic_text: self.italic_text_from_matches(),
        highlighted_lines: self.highlighted_lines_from_matches()?,
        use_custom_assets: self.custom_assets_from_matches(),
        #[cfg(feature = "lessopen")]
        use_lessopen: self.matches.get_flag("lessopen"),
        set_terminal_title: self.terminal_title_from_matches(),
        squeeze_lines: self.squeeze_lines_from_matches(),
    })
}

fn syntax_mapping_from_matches(&self) -> Result<SyntaxMapping> {
    let mut syntax_mapping = SyntaxMapping::new();
    // start building glob matchers for builtin mappings immediately
    // this is an appropriate approach because it's statistically likely that
    // all the custom mappings need to be checked
    syntax_mapping.start_offload_build_all();

    if let Some(values) = self.matches.get_many::<String>("ignored-suffix") {
        for suffix in values {
            syntax_mapping.insert_ignored_suffix(suffix);
        }
    }

    if let Some(values) = self.matches.get_many::<String>("map-syntax") {
        // later args take precedence over earlier ones, hence `.rev()`
        // see: https://github.com/sharkdp/bat/pull/2755#discussion_r1456416875
        for from_to in values.rev() {
            let parts: Vec<_> = from_to.split(':').collect();

            if parts.len() != 2 {
                return Err("Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.".into());
            }

            syntax_mapping.insert(parts[0], MappingTarget::MapTo(parts[1]))?;
        }
    }

    Ok(syntax_mapping)
}

fn terminal_width_from_matches(&self) -> Option<usize> {
    self.matches
        .get_one::<String>("terminal-width")
        .and_then(|w| {
            if w.starts_with('+') || w.starts_with('-') {
                // Treat argument as a delta to the current terminal width
                w.parse().ok().map(|delta: i16| {
                    let old_width: u16 = Term::stdout().size().1;
                    let new_width: i32 = i32::from(old_width) + i32::from(delta);

                    if new_width <= 0 {
                        old_width as usize
                    } else {
                        new_width as usize
                    }
                })
            } else {
                w.parse().ok()
            }
        })
}

fn language_from_matches(&self) -> Option<&str> {
    self.matches
        .get_one::<String>("language")
        .map(|s| s.as_str())
        .or_else(|| {
            if self.matches.get_flag("show-all") {
                Some("show-nonprintable")
            } else {
                None
            }
        })
}

fn nonprintable_notation_from_matches(&self) -> NonprintableNotation {
    match self
        .matches
        .get_one::<String>("nonprintable-notation")
        .map(|s| s.as_str())
    {
        Some("unicode") => NonprintableNotation::Unicode,
        Some("caret") => NonprintableNotation::Caret,
        _ => unreachable!("other values for --nonprintable-notation are not allowed"),
    }
}

fn binary_behavior_from_matches(&self) -> BinaryBehavior {
    match self.matches.get_one::<String>("binary").map(|s| s.as_str()) {
        Some("as-text") => BinaryBehavior::AsText,
        Some("no-printing") => BinaryBehavior::NoPrinting,
        _ => unreachable!("other values for --binary are not allowed"),
    }
}

